describe("planRestamp — repairing the unstamped (#4207)", () => {
  // The packaged seed, and a store copy of the SAME id that lost its `builtin` flag to a pre-#4197
  // partial write AND has since been independently edited (the real shape: harvests kept updating the
  // store copy while the reconcile skipped it, so the two drifted apart in both directions).
  const seeded = stampSeedHash(comp({ version: "2.0.0", name: "Button" }));
  const unstamped = comp({ version: "1.0.0", name: "ButtonTab", builtin: undefined, seedHash: undefined });

  it("stamps a record that a packaged seed exists for", () => {
    const { stamps, deferred } = planRestamp([unstamped], [seeded]);
    expect(stamps).toHaveLength(1);
    expect(stamps[0].builtin).toBe(true);
    expect(deferred).toEqual([]);
  });

  it("leaves the content completely untouched", () => {
    const { stamps } = planRestamp([unstamped], [seeded]);
    const { builtin: _b, seedHash: _h, ...after } = stamps[0];
    const { builtin: _b2, seedHash: _h2, ...before } = unstamped;
    expect(after).toEqual(before);
  });

  // THE design decision. Stamped with the SEED's hash the record reads as EDITED against an UNMOVED
  // seed, which is the verdict that KEEPS the store copy. Stamped with its OWN hash it would read as
  // pristine-and-stale — the REFRESH verdict — and the next hydrate would replace the store content
  // with the seed's. This test is the difference between a repair and a silent data loss.
  it("claims a builtin that LOST its stamp — the #63 shape", () => {
    // #a-builtin-that-lost-its-stamp-falls-between-both-guards. `planRestamp` used to skip ANY record
    // carrying `builtin`, commented "already in the reconcile path". A builtin that has lost its
    // `seedHash` is NOT: the reconcile computes `contentHash` as undefined when `seedHash` is, so
    // `modified` is false, the seed has moved, and the `!modified && seedMoved` branch adopts the
    // packaged copy. Each guard assumed the other covered it, so nothing did.
    //
    // That is what happened to 38 records on 2026-08-14 (designer request #63): a `--graph` LITE
    // `--replace` push strips the stamp — that projection carries no `seedHash` — and the next hydrate
    // overwrote a designer's edits with the seed.
    const strippedBuiltin = comp({ version: "1.0.0", name: "ButtonEdited", builtin: true, seedHash: undefined });
    const { stamps } = planRestamp([strippedBuiltin], [seeded]);
    expect(stamps, "a stamp-less builtin must be re-claimed, not skipped").toHaveLength(1);
    expect(stamps[0].seedHash).toBe(seeded.seedHash);

    // And with the stamp restored, the reconcile KEEPS the edited store copy instead of refreshing it.
    const r = reconcileSeed(applyStamps([strippedBuiltin], stamps), [seeded], "component");
    expect(r.pushes, "the packaged copy must NOT be pushed over the designer's edit").toEqual([]);
    expect(r.records[0].name).toBe("ButtonEdited");
  });

  it("still skips a FULLY stamped builtin — the reconcile path is unchanged for those", () => {
    // The guard narrows, it does not disappear: a record that is correctly stamped is still the
    // reconcile's business alone, so the ordinary refresh/keep behaviour is untouched.
    const healthy = stampSeedHash(comp({ version: "1.0.0", name: "Button", builtin: true }));
    expect(planRestamp([healthy], [seeded]).stamps).toEqual([]);
  });

  it("still refuses to claim a record with NO packaged seed", () => {
    // Restamp must never invent provenance for genuinely user-authored work, stamp or no stamp.
    const mine = comp({ id: "mine", name: "Mine", builtin: true, seedHash: undefined });
    expect(planRestamp([mine], [seeded]).stamps).toEqual([]);
  });

  it("stamps with the SEED's hash, so the next reconcile KEEPS the store copy", () => {
    const { stamps } = planRestamp([unstamped], [seeded]);
    expect(stamps[0].seedHash).toBe(seeded.seedHash);
    expect(stamps[0].seedHash).not.toBe(seedHashOf(unstamped));

    const r = reconcileSeed(stamps, [seeded], "component");
    expect(r.records).toEqual(stamps); // the store copy survived
    expect(r.pushes).toEqual([]);
    expect(r.notices).toEqual([]); // seed has not moved since — nothing to report yet
  });

  it("surfaces updated-upstream once the seed DOES move, which is the point of rejoining", () => {
    const { stamps } = planRestamp([unstamped], [seeded]);
    const seedMoved = stampSeedHash(comp({ version: "3.0.0", name: "Button" }));
    const r = reconcileSeed(stamps, [seedMoved], "component");
    expect(r.records).toEqual(stamps); // still kept — it is an edited built-in
    expect(r.notices).toEqual([{ kind: "updated-upstream", type: "component", id: "button", name: "ButtonTab" }]);
  });

  it("never claims a record with no packaged seed — that is a genuinely user-authored one", () => {
    const authored = comp({ id: "my-thing", builtin: undefined, seedHash: undefined });
    expect(planRestamp([authored], [seeded]).stamps).toEqual([]);
  });

  it("skips records already in the reconcile path, and suppression tombstones", () => {
    const tombstone = comp({ builtin: undefined, seedHash: undefined, suppressed: true });
    expect(planRestamp([seeded, tombstone], [seeded]).stamps).toEqual([]);
  });

  // Stamping a seed-authoritative record arms the branch that forces the seed over the store BEFORE any
  // content comparison — so the "repair" would change what the app renders. Defer, and say so.
  it("defers a seed-authoritative record instead of stamping it", () => {
    const page = comp({ id: "fleetpage", name: "FleetPage", role: "page", builtin: undefined, seedHash: undefined });
    const seedPage = stampSeedHash(comp({ id: "fleetpage", name: "FleetPage", role: "page", version: "2.0.0" }));
    const { stamps, deferred } = planRestamp([page], [seedPage], { seedAuthoritative: (r) => r.role === "page" });
    expect(stamps).toEqual([]);
    expect(deferred).toEqual([{ id: "fleetpage", name: "FleetPage", reason: "seed-authoritative" }]);
  });
});

describe("applyStamps + the repair running INSIDE hydrate (auto-restamp)", () => {
  it("replaces stamped records by id and leaves the rest alone", () => {
    const a = comp({ id: "a", builtin: false });
    const b = comp({ id: "b", builtin: false });
    const stamped = { ...a, builtin: true, seedHash: "H" };
    const out = applyStamps([a, b], [stamped]);
    expect(out[0]).toBe(stamped);
    expect(out[1], "an untouched record keeps its identity").toBe(b);
  });

  it("returns the SAME array reference when there is nothing to stamp", () => {
    // The common case after the first repair — so hydrate pays nothing on every subsequent boot.
    const loaded = [comp({ id: "a" })];
    expect(applyStamps(loaded, [])).toBe(loaded);
  });

  it("a DIVERGED store copy survives the repair with its content intact", () => {
    // The property the whole design rests on. The store copy differs from the seed; stamping with the
    // SEED's hash makes it read as edited-against-an-unmoved-seed, which KEEPS the store copy. Stamping
    // with its OWN hash would read as pristine-and-stale and hand the seed's content over the top.
    const seeded = stampSeedHash(comp({ id: "history", srcText: "OLD seed body" }));
    const store = comp({ id: "history", srcText: "NEW store body", builtin: false });

    const plan = planRestamp([store], [seeded]);
    expect(plan.stamps).toHaveLength(1);
    expect(plan.stamps[0].seedHash).toBe(seeded.seedHash);

    const reconciled = reconcileSeed(applyStamps([store], plan.stamps), [seeded], "component");
    const kept = reconciled.records.find((r) => r.id === "history");
    expect(kept?.srcText, "the store copy is kept — the repair restores membership, not content").toBe("NEW store body");
  });

  it("an IDENTICAL store copy is stamped and simply agrees with its seed — the 214-record case", () => {
    // What promoting store-only records into the seed produced: a seed created for an id whose store
    // copy carries no `builtin` flag, so it read as unstamped despite being byte-identical.
    const seeded = stampSeedHash(comp({ id: "same", srcText: "body" }));
    const store = comp({ id: "same", srcText: "body", builtin: false });
    const plan = planRestamp([store], [seeded]);
    const reconciled = reconcileSeed(applyStamps([store], plan.stamps), [seeded], "component");
    expect(reconciled.records.find((r) => r.id === "same")?.srcText).toBe("body");
    expect(reconciled.notices.filter((n) => n.kind === "unstamped"), "repaired ⇒ no notice").toEqual([]);
  });

  it("a record with NO packaged seed is never stamped — that is the user-authored signature", () => {
    const mine = comp({ id: "mine", builtin: false });
    expect(planRestamp([mine], []).stamps).toEqual([]);
    // …and it still reaches the reconciled output, untouched.
    const reconciled = reconcileSeed([mine], [], "component");
    expect(reconciled.records.find((r) => r.id === "mine")).toBeTruthy();
  });
});

import { describe, it, expect } from "vitest";
import { reconcileSeed } from "@/features/designs/lib/seedRefresh";

type Rec = { id: string; name?: string; srcText?: string; builtin?: boolean; seedHash?: string };

const seed = (id: string, srcText: string): Rec => ({ id, name: id, srcText, builtin: true });

describe("an EMPTY store copy is not a competing edit", () => {
  /**
   * THE BUG. Eight packaged components sat in the store with a zero-length `srcText` while their seed
   * carried real source — `dropdown` (7,846 bytes), `activityfeed` (3,940), `windowcontrols`,
   * `backbutton`, `cardlistrow`, `inlineerror`, `skillsdigesttoggle`, `settingssubheader`. They had
   * also lost their `builtin`/`seedHash` stamp to a pre-#4197 partial write, so the reconcile
   * classified them as user-authored and never touched them: the app rendered an empty component and
   * the seed's version could never arrive.
   *
   * #4216 deliberately left unstamped records alone because "which side is right" is a per-record
   * judgement. That caution is about a store copy holding DIFFERENT work. A copy holding NOTHING is
   * not a competing edit — it is a record that lost its content, and there is nothing to weigh.
   */
  it("restores an unstamped, EMPTY record from the seed", () => {
    const loaded: Rec[] = [{ id: "dropdown", name: "Dropdown", srcText: "" }];
    const out = reconcileSeed(loaded, [seed("dropdown", "export function Dropdown() {}")], "component");
    expect(out.records[0].srcText, "the seed's source is what renders now").toContain("Dropdown");
    expect(out.pushes.map((p) => p.id), "and it is written back, so it stops being empty").toEqual(["dropdown"]);
    expect(out.notices.some((n) => n.kind === "refreshed" && n.id === "dropdown")).toBe(true);
  });

  it("still leaves an unstamped record that has REAL content alone", () => {
    // The #4216 caution stands wherever there is something to lose: the drift runs both ways, and a
    // reconcile that silently replaced a page someone had authored would be the worse bug.
    const loaded: Rec[] = [{ id: "guidecard", name: "GuideCard", srcText: "the user's own work" }];
    const out = reconcileSeed(loaded, [seed("guidecard", "the shipped version")], "component");
    expect(out.records[0].srcText).toBe("the user's own work");
    expect(out.pushes).toEqual([]);
    expect(out.notices.some((n) => n.kind === "unstamped")).toBe(true);
  });

  it("does not invent content when the SEED is the empty one", () => {
    // Narrow on purpose. An empty seed record is a real (if odd) state; replacing a store copy with
    // nothing would be this bug pointed the other way.
    const loaded: Rec[] = [{ id: "x", name: "X", srcText: "" }];
    const out = reconcileSeed(loaded, [seed("x", "   ")], "component");
    expect(out.pushes).toEqual([]);
  });

  it("leaves a genuinely user-authored record untouched — it has no seed at all", () => {
    const loaded: Rec[] = [{ id: "mine", name: "Mine", srcText: "" }];
    const out = reconcileSeed(loaded, [], "component");
    expect(out.records.map((r) => r.id)).toEqual(["mine"]);
    expect(out.pushes).toEqual([]);
  });
});
